import script from './data/script.json';
import timingJson from './data/timing.json';
import { FPS } from './theme';

// Generated by scripts/tts.py; scenes without measured audio are estimated.
const timing = timingJson as Record<string, number[]>;

export interface Segment {
  text: string;
  cite: string;
}

export interface SceneData {
  id: string;
  chapter?: string;
  title: string;
  steph?: string;
  segments: Segment[];
}

export interface SceneTiming {
  scene: SceneData;
  from: number;
  duration: number;
  /** Segment start frames, relative to the scene start. */
  starts: number[];
  /** Segment lengths in frames (narration only). */
  durs: number[];
  /** Frame at which narration (and the scene's own visuals) begin. */
  body: number;
}

export const CARD = Math.round(2.6 * FPS);
const LEAD = Math.round(0.5 * FPS);
const GAP = Math.round(0.55 * FPS);
const TAIL = Math.round(1.1 * FPS);

const estimate = (text: string) => text.split(/\s+/).length / 2.35;

export const scenes = (script as { scenes: SceneData[] }).scenes;

function build(): SceneTiming[] {
  let cursor = 0;
  return scenes.map((scene) => {
    const secs = timing[scene.id] ?? scene.segments.map((s) => estimate(s.text));
    const body = (scene.chapter ? CARD : 0) + LEAD;
    const starts: number[] = [];
    const durs: number[] = [];
    let t = body;
    secs.forEach((s) => {
      const d = Math.ceil(s * FPS);
      starts.push(t);
      durs.push(d);
      t += d + GAP;
    });
    const duration = t - GAP + TAIL;
    const entry = { scene, from: cursor, duration, starts, durs, body };
    cursor += duration;
    return entry;
  });
}

export const TIMELINE = build();
export const TOTAL_FRAMES = TIMELINE.reduce((n, s) => n + s.duration, 0) + Math.round(26 * FPS);
export const CREDITS_FROM = TIMELINE.reduce((n, s) => n + s.duration, 0);

export const timingOf = (id: string): SceneTiming => {
  const t = TIMELINE.find((s) => s.scene.id === id);
  if (!t) throw new Error(`unknown scene ${id}`);
  return t;
};
